-- honeydoo schema. Generated by npm run db:bolt from db/migrations. Do not edit; add a new migration instead.
-- honeydoo database, generated by npm run db:bundle. Run once on an empty Supabase project.
-- ===== 001_init.sql =====
-- Honeydoo core schema.
-- Money is always integer minor units (cents). Timestamps are timestamptz (UTC).
-- Demo data is isolated by merchants.is_demo and can be removed with one statement.


create table markets (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique,
  name          text not null,
  state         text not null,
  latitude      double precision,
  longitude     double precision,
  active        boolean not null default true,
  created_at    timestamptz not null default now()
);

create table categories (
  id            uuid primary key default gen_random_uuid(),
  name          text not null,
  slug          text not null unique,
  parent_id     uuid references categories(id) on delete set null,
  display_order int not null default 0
);

create table merchants (
  id                  uuid primary key default gen_random_uuid(),
  market_id           uuid references markets(id),
  legal_name          text not null,
  display_name        text not null,
  slug                text not null unique,
  description         text not null default '',
  category            text not null,
  status              text not null default 'onboarding'
                        check (status in ('onboarding','pending_review','active','paused','disconnected')),
  is_demo             boolean not null default false,
  logo_url            text,
  cover_image_url     text,
  contact_email       text,
  contact_phone       text,
  website_url         text,
  service_fee_enabled boolean not null default true,
  service_fee_minor   int not null default 100 check (service_fee_minor >= 0),
  referral_code       text unique,
  activated_at        timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index merchants_market_status_idx on merchants(market_id, status);

-- People who can manage a merchant (maps to auth users in production).
create table merchant_members (
  id           uuid primary key default gen_random_uuid(),
  merchant_id  uuid not null references merchants(id) on delete cascade,
  user_ref     text not null,          -- auth provider user id or verified email
  role         text not null default 'owner' check (role in ('owner','manager','staff')),
  created_at   timestamptz not null default now(),
  unique (merchant_id, user_ref)
);

create table merchant_locations (
  id                 uuid primary key default gen_random_uuid(),
  merchant_id        uuid not null references merchants(id) on delete cascade,
  source_provider    text not null default 'manual',
  source_location_id text,
  name               text not null,
  address            text not null default '',
  neighborhood       text,
  city               text not null default '',
  state              text not null default '',
  postal_code        text not null default '',
  latitude           double precision,
  longitude          double precision,
  timezone           text not null default 'America/New_York',
  operating_hours    jsonb not null default '{}'::jsonb,
  pickup_hours       jsonb,
  pickup_enabled     boolean not null default false,
  pickup_prep_minutes int not null default 15,
  tax_rate_bps       int not null default 0,   -- demo/manual tax only; Square computes its own
  active             boolean not null default false,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (merchant_id, source_provider, source_location_id)
);
create index merchant_locations_merchant_idx on merchant_locations(merchant_id);

create table merchant_integrations (
  id                              uuid primary key default gen_random_uuid(),
  merchant_id                     uuid not null references merchants(id) on delete cascade,
  provider                        text not null check (provider in ('square','shopify','clover','toast','demo')),
  environment                     text not null default 'sandbox' check (environment in ('sandbox','production','demo')),
  provider_merchant_id            text not null,
  encrypted_credentials_reference text,     -- AES-256-GCM envelope, never plaintext
  granted_scopes                  text[] not null default '{}',
  token_expires_at                timestamptz,
  authorized_at                   timestamptz,
  connection_status               text not null default 'connected'
                                    check (connection_status in ('connected','needs_reauth','revoked','error','disconnected')),
  last_sync_at                    timestamptz,
  last_error                      text,
  created_at                      timestamptz not null default now(),
  updated_at                      timestamptz not null default now(),
  unique (provider, environment, provider_merchant_id)
);
create index merchant_integrations_merchant_idx on merchant_integrations(merchant_id);

create table oauth_states (
  state          text primary key,
  provider       text not null,
  merchant_id    uuid references merchants(id) on delete cascade,
  initiated_by   text,
  redirect_after text,
  created_at     timestamptz not null default now(),
  expires_at     timestamptz not null,
  consumed_at    timestamptz
);

create table products (
  id                 uuid primary key default gen_random_uuid(),
  merchant_id        uuid not null references merchants(id) on delete cascade,
  source_provider    text not null default 'manual',
  source_item_id     text not null,
  name               text not null,
  description        text not null default '',
  category_id        uuid references categories(id),
  source_category    text,
  tags               text[] not null default '{}',
  primary_image_url  text,
  taxable            boolean not null default true,
  publication_status text not null default 'draft'
                       check (publication_status in ('draft','published','hidden','archived','deleted_at_source')),
  source_version     bigint,
  source_updated_at  timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (merchant_id, source_provider, source_item_id)
);
create index products_merchant_idx on products(merchant_id, publication_status);
create index products_category_idx on products(category_id);

-- Honeydoo-only presentation overrides. Never written back to the merchant's POS.
create table product_overrides (
  product_id               uuid primary key references products(id) on delete cascade,
  published_in_honeydoo    boolean,
  featured_image_url       text,
  marketplace_description  text,
  featured                 boolean not null default false,
  updated_by               text,
  updated_at               timestamptz not null default now()
);

create table product_variations (
  id                  uuid primary key default gen_random_uuid(),
  product_id          uuid not null references products(id) on delete cascade,
  source_variation_id text not null,
  name                text not null,
  sku                 text,
  price_minor_units   int not null check (price_minor_units >= 0),
  currency            text not null default 'USD',
  available_for_sale  boolean not null default true,
  track_inventory     boolean not null default false,
  ordinal             int not null default 0,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (product_id, source_variation_id)
);

create table modifier_lists (
  id              uuid primary key default gen_random_uuid(),
  merchant_id     uuid not null references merchants(id) on delete cascade,
  source_provider text not null default 'manual',
  source_id       text not null,
  name            text not null,
  selection_type  text not null default 'single' check (selection_type in ('single','multiple')),
  min_selected    int not null default 0,
  max_selected    int,
  unique (merchant_id, source_provider, source_id)
);

create table modifiers (
  id                uuid primary key default gen_random_uuid(),
  modifier_list_id  uuid not null references modifier_lists(id) on delete cascade,
  source_id         text not null,
  name              text not null,
  price_minor_units int not null default 0 check (price_minor_units >= 0),
  ordinal           int not null default 0,
  is_default        boolean not null default false,
  unique (modifier_list_id, source_id)
);

create table product_modifier_lists (
  product_id       uuid not null references products(id) on delete cascade,
  modifier_list_id uuid not null references modifier_lists(id) on delete cascade,
  ordinal          int not null default 0,
  primary key (product_id, modifier_list_id)
);

create table product_location_availability (
  id                   uuid primary key default gen_random_uuid(),
  variation_id         uuid not null references product_variations(id) on delete cascade,
  merchant_location_id uuid not null references merchant_locations(id) on delete cascade,
  quantity             int,                    -- null when the source does not track stock
  availability_status  text not null default 'available'
                         check (availability_status in ('in_stock','low_stock','out_of_stock','available','unknown','not_sold_here')),
  source_updated_at    timestamptz,
  last_checked_at      timestamptz not null default now(),
  unique (variation_id, merchant_location_id)
);

create table customers (
  id          uuid primary key default gen_random_uuid(),
  email       text unique,
  name        text,
  phone       text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table carts (
  id          uuid primary key default gen_random_uuid(),
  customer_id uuid references customers(id) on delete set null,
  session_id  text not null,
  status      text not null default 'open' check (status in ('open','converted','abandoned')),
  version     int not null default 1,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index carts_session_idx on carts(session_id, status);

create table cart_items (
  id                   uuid primary key default gen_random_uuid(),
  cart_id              uuid not null references carts(id) on delete cascade,
  product_variation_id uuid not null references product_variations(id) on delete cascade,
  merchant_location_id uuid not null references merchant_locations(id) on delete cascade,
  quantity             int not null check (quantity between 1 and 50),
  selected_modifiers   jsonb not null default '[]'::jsonb,   -- array of modifier ids
  line_key             text not null,                         -- variation + sorted modifiers
  created_at           timestamptz not null default now(),
  unique (cart_id, line_key)
);

create table orders (
  id                    uuid primary key default gen_random_uuid(),
  public_code           text not null unique,
  customer_id           uuid references customers(id) on delete set null,
  session_id            text,
  cart_id               uuid references carts(id) on delete set null,
  merchant_id           uuid not null references merchants(id),
  merchant_location_id  uuid not null references merchant_locations(id),
  provider              text not null,
  provider_order_id     text,
  idempotency_key       text not null unique,
  status                text not null default 'awaiting_payment'
                          check (status in ('awaiting_payment','payment_not_configured','paid','accepted','ready',
                                            'completed','canceled','payment_failed','expired','refunded',
                                            'partially_refunded','needs_reconciliation')),
  fulfillment_type      text not null default 'pickup' check (fulfillment_type in ('pickup')),
  merchandise_subtotal  int not null,
  tax_total             int not null default 0,
  service_fee           int not null default 0,
  service_fee_waived    boolean not null default false,
  discount_total        int not null default 0,
  tip_total             int not null default 0,
  grand_total           int not null,
  currency              text not null default 'USD',
  pickup_details        jsonb not null default '{}'::jsonb,
  contact_email         text,
  contact_name          text,
  referral_source       text,
  quote_hash            text not null,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  check (grand_total = merchandise_subtotal + tax_total + service_fee + tip_total - discount_total)
);
create index orders_merchant_idx on orders(merchant_id, created_at desc);
create index orders_session_idx on orders(session_id, created_at desc);
create index orders_customer_idx on orders(customer_id, created_at desc);
create unique index orders_provider_order_idx on orders(provider, provider_order_id) where provider_order_id is not null;

create table order_items (
  id                    uuid primary key default gen_random_uuid(),
  order_id              uuid not null references orders(id) on delete cascade,
  product_id            uuid references products(id) on delete set null,
  variation_id          uuid references product_variations(id) on delete set null,
  source_variation_id   text not null,
  product_name_snapshot text not null,
  variation_name_snapshot text not null,
  unit_price_snapshot   int not null,
  quantity              int not null check (quantity > 0),
  modifier_snapshot     jsonb not null default '[]'::jsonb,
  taxable               boolean not null default true,
  line_total            int not null
);

create table order_status_history (
  id          bigserial primary key,
  order_id    uuid not null references orders(id) on delete cascade,
  from_status text,
  to_status   text not null,
  reason      text,
  actor       text not null,
  created_at  timestamptz not null default now()
);
create index order_status_history_order_idx on order_status_history(order_id, created_at);

create table payments (
  id                  uuid primary key default gen_random_uuid(),
  order_id            uuid not null references orders(id) on delete cascade,
  provider            text not null,
  provider_payment_id text,
  provider_link_id    text,
  checkout_url        text,
  status              text not null default 'created'
                        check (status in ('created','not_configured','pending','approved','completed','failed','canceled','expired')),
  amount              int not null,
  application_fee     int not null default 0,
  processing_fee      int,
  refunded_amount     int not null default 0,
  currency            text not null default 'USD',
  expires_at          timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create unique index payments_provider_payment_idx on payments(provider, provider_payment_id) where provider_payment_id is not null;
create index payments_order_idx on payments(order_id);

create table refunds (
  id                 uuid primary key default gen_random_uuid(),
  order_id           uuid not null references orders(id) on delete cascade,
  payment_id         uuid references payments(id) on delete set null,
  provider_refund_id text,
  amount             int not null check (amount > 0),
  fee_refunded       int not null default 0,
  status             text not null default 'pending' check (status in ('pending','completed','failed','rejected')),
  reason             text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create unique index refunds_provider_idx on refunds(provider_refund_id) where provider_refund_id is not null;

-- One ledger row per paid order. Separates merchant proceeds from Honeydoo revenue.
create table transactions (
  id                            uuid primary key default gen_random_uuid(),
  order_id                      uuid not null unique references orders(id) on delete cascade,
  merchant_id                   uuid not null references merchants(id),
  gross_amount                  int not null,
  merchandise_subtotal          int not null,
  tax_total                     int not null,
  discount_total                int not null,
  tip_total                     int not null,
  honeydoo_revenue              int not null,
  processing_cost               int,          -- merchant-borne card processing, when reported
  honeydoo_variable_cost        int not null default 0,
  merchant_proceeds             int,
  refunds                       int not null default 0,
  estimated_contribution_margin int not null,
  settlement_status             text not null default 'pending' check (settlement_status in ('pending','settled','reversed')),
  created_at                    timestamptz not null default now(),
  updated_at                    timestamptz not null default now()
);

create table sync_jobs (
  id             uuid primary key default gen_random_uuid(),
  integration_id uuid not null references merchant_integrations(id) on delete cascade,
  job_type       text not null check (job_type in ('full_import','reconcile','webhook_update','manual_resync','inventory')),
  status         text not null default 'queued' check (status in ('queued','running','succeeded','failed')),
  attempts       int not null default 0,
  run_after      timestamptz not null default now(),
  stats          jsonb not null default '{}'::jsonb,
  started_at     timestamptz,
  finished_at    timestamptz,
  error_details  text,
  created_at     timestamptz not null default now()
);
create index sync_jobs_queue_idx on sync_jobs(status, run_after);

create table webhook_events (
  id                uuid primary key default gen_random_uuid(),
  provider          text not null,
  provider_event_id text not null,
  event_type        text not null,
  merchant_ref      text,
  payload           jsonb not null,
  received_at       timestamptz not null default now(),
  processed_at      timestamptz,
  attempts          int not null default 0,
  status            text not null default 'received' check (status in ('received','processed','ignored','failed')),
  error_details     text,
  unique (provider, provider_event_id)
);

create table merchant_consents (
  id            uuid primary key default gen_random_uuid(),
  merchant_id   uuid not null references merchants(id) on delete cascade,
  consent_type  text not null check (consent_type in ('merchant_terms','data_access','service_fee','marketing')),
  terms_version text not null,
  accepted_by   text not null,
  accepted_ip   text,
  accepted_at   timestamptz not null default now()
);
create index merchant_consents_merchant_idx on merchant_consents(merchant_id, consent_type);

create table analytics_events (
  id          bigserial primary key,
  event       text not null,
  session_id  text,
  customer_id uuid,
  merchant_id uuid,
  product_id  uuid,
  order_id    uuid,
  properties  jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);
create index analytics_events_event_idx on analytics_events(event, created_at);

create table audit_log (
  id          bigserial primary key,
  actor       text not null,
  action      text not null,
  entity      text not null,
  entity_id   text,
  details     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);

create table ai_requests (
  id            bigserial primary key,
  session_id    text,
  provider      text not null,
  model         text,
  used_fallback boolean not null default false,
  latency_ms    int,
  input_tokens  int,
  output_tokens int,
  result_count  int,
  rejected_ids  int not null default 0,
  error         text,
  created_at    timestamptz not null default now()
);

-- ===== 002_merchant_paid_fee.sql =====
-- Fee model: the merchant pays Honeydoo's flat per-order fee (Bites-style). Customers pay the shop's
-- regular prices plus tax only. orders.service_fee is kept for history and is 0 for new orders.
alter table orders add column merchant_fee int not null default 0 check (merchant_fee >= 0);
alter table orders add column merchant_fee_waived boolean not null default false;
-- Fee owed by the merchant but not collected through the processor (for example, app-fee permission
-- not granted). Invoiced separately.
alter table transactions add column fee_receivable int not null default 0;
comment on column merchants.service_fee_enabled is 'Honeydoo per-order merchant fee applies (admin can waive for promotions)';
comment on column merchants.service_fee_minor is 'Honeydoo per-order merchant fee in cents';

-- ===== 003_customer_accounts.sql =====
-- Customer accounts: email and password sign-in, server-side sessions, password reset tokens.
-- Browsing and guest checkout never require an account.

alter table customers add column password_hash text;
alter table customers add column email_verified_at timestamptz;
alter table customers add column deleted_at timestamptz;
create unique index customers_email_lower_idx on customers (lower(email)) where email is not null;

-- Opaque session tokens. Only a SHA-256 of the token is stored, so a database leak cannot be replayed.
create table customer_sessions (
  id           uuid primary key default gen_random_uuid(),
  customer_id  uuid not null references customers(id) on delete cascade,
  token_hash   text not null unique,
  created_at   timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  expires_at   timestamptz not null,
  revoked_at   timestamptz
);
create index customer_sessions_customer_idx on customer_sessions(customer_id);

create table password_resets (
  id          uuid primary key default gen_random_uuid(),
  customer_id uuid not null references customers(id) on delete cascade,
  token_hash  text not null unique,
  expires_at  timestamptz not null,
  used_at     timestamptz,
  created_at  timestamptz not null default now()
);

create index carts_customer_idx on carts(customer_id, status);

-- ===== 004_staff_accounts.sql =====
-- honeydoo staff (admin dashboard) accounts: invite-only, password + authenticator code, server-side sessions.

create table staff_users (
  id                uuid primary key default gen_random_uuid(),
  email             text not null,
  name              text not null,
  role              text not null default 'analyst' check (role in ('owner','analyst')),
  password_hash     text,
  totp_secret_enc   text,                 -- AES-256-GCM envelope, never plaintext
  totp_enabled_at   timestamptz,
  totp_last_step    bigint not null default 0,  -- blocks reuse of a code that already worked
  failed_attempts   int not null default 0,
  locked_until      timestamptz,
  last_login_at     timestamptz,
  disabled_at       timestamptz,
  invited_by        uuid references staff_users(id),
  created_at        timestamptz not null default now()
);
create unique index staff_users_email_idx on staff_users (lower(email));

create table staff_invites (
  id          uuid primary key default gen_random_uuid(),
  staff_id    uuid not null references staff_users(id) on delete cascade,
  token_hash  text not null unique,
  expires_at  timestamptz not null,
  used_at     timestamptz,
  created_at  timestamptz not null default now()
);

create table staff_sessions (
  id          uuid primary key default gen_random_uuid(),
  staff_id    uuid not null references staff_users(id) on delete cascade,
  token_hash  text not null unique,
  created_at  timestamptz not null default now(),
  expires_at  timestamptz not null,
  revoked_at  timestamptz
);
create index staff_sessions_staff_idx on staff_sessions(staff_id);

-- ===== row-level security =====
-- Apply on Supabase after the core migrations (npm run db:migrate -- --supabase).
-- The Honeydoo server connects with a privileged role and enforces authorization in code.
-- These policies make the anon/authenticated keys safe if they are ever used directly:
-- public catalog data is readable when the merchant is active; everything else is denied
-- unless the caller is a member of the merchant.

do $$
declare t text;
begin
  foreach t in array array[
    'markets','categories','merchants','merchant_members','merchant_locations','merchant_integrations',
    'oauth_states','products','product_overrides','product_variations','modifier_lists','modifiers',
    'product_modifier_lists','product_location_availability','customers','carts','cart_items','orders',
    'order_items','order_status_history','payments','refunds','transactions','sync_jobs','webhook_events',
    'merchant_consents','analytics_events','audit_log','ai_requests','customer_sessions','password_resets','staff_users','staff_invites','staff_sessions']
  loop
    execute format('alter table %I enable row level security', t);
    execute format('alter table %I force row level security', t);
  end loop;
end $$;

create or replace function public.is_merchant_member(mid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from merchant_members m where m.merchant_id = mid and m.user_ref = auth.uid()::text)
$$;

-- Public catalog (read only, active merchants only)
create policy public_markets on markets for select using (active);
create policy public_categories on categories for select using (true);
create policy public_merchants on merchants for select using (status = 'active' or is_merchant_member(id));
create policy public_locations on merchant_locations for select
  using ((active and exists (select 1 from merchants m where m.id = merchant_id and m.status = 'active')) or is_merchant_member(merchant_id));
create policy public_products on products for select
  using ((publication_status = 'published' and exists (select 1 from merchants m where m.id = merchant_id and m.status = 'active')) or is_merchant_member(merchant_id));
create policy public_variations on product_variations for select
  using (exists (select 1 from products p where p.id = product_id and (p.publication_status = 'published' or is_merchant_member(p.merchant_id))));

-- Merchant-scoped data
create policy member_orders on orders for select using (is_merchant_member(merchant_id));
create policy member_integrations on merchant_integrations for select using (is_merchant_member(merchant_id));
create policy member_consents on merchant_consents for select using (is_merchant_member(merchant_id));
create policy member_transactions on transactions for select using (is_merchant_member(merchant_id));
-- All other tables: no policies, so only the server role can access them.

create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now());
alter table schema_migrations enable row level security;
insert into schema_migrations(name) values ('001_init.sql'), ('002_merchant_paid_fee.sql'), ('003_customer_accounts.sql'), ('004_staff_accounts.sql') on conflict do nothing;
